/**
 * HealthCheck - Performs a comprehensive health check on the target node.
 * Returns a map with health status details.
 */

function checkConnectivity(node)
{
  local result = {};
  result['pingStatus'] = node.icmpAverageRTT < 100 ? 'OK' : 'DEGRADED';
  result['pingRTT'] = node.icmpAverageRTT;
  return result;
}

function checkAgent(node)
{
  local result = {};
  result['agentStatus'] = node.isAgent ? 'CONNECTED' : 'N/A';
  if (node.isAgent)
  {
    result['agentVersion'] = AgentGetParameterValue(node, 'Agent.Version');
    result['cpuUsage'] = AgentGetParameterValue(node, 'System.CPU.Usage');
    result['memFree'] = AgentGetParameterValue(node, 'System.Memory.Physical.FreePerc');
  }
  return result;
}

local node = $node;
local report = {};

report['node'] = node.name;
report['timestamp'] = FormatDate(time(), '%Y-%m-%d %H:%M:%S');
report['connectivity'] = checkConnectivity(node);
report['agent'] = checkAgent(node);
report['overallStatus'] = (report['connectivity']['pingStatus'] == 'OK') ? 'HEALTHY' : 'DEGRADED';

return report;
